import{_ as e,o as t,c as r,a4 as i}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Gruhapravesha source profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/33-gruhapravesha-evidence-audit.md","filePath":"reference/33-gruhapravesha-evidence-audit.md","lastUpdated":1788593217000}'),n={name:"reference/33-gruhapravesha-evidence-audit.md"};function s(o,a,d,h,c,u){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="gruhapravesha-source-profile" tabindex="-1">Gruhapravesha source profile <a class="header-anchor" href="#gruhapravesha-source-profile" aria-label="Permalink to &quot;Gruhapravesha source profile&quot;">​</a></h1><h2 id="status-and-ritual-boundary" tabindex="-1">Status and ritual boundary <a class="header-anchor" href="#status-and-ritual-boundary" aria-label="Permalink to &quot;Status and ritual boundary&quot;">​</a></h2><p><code>gruhapravesha</code> is a source-verified Raman-lineage profile for the first ceremonial entry into a newly built home. It is not the election for buying a completed house, moving into a rental, returning after renovation, or laying a foundation or roof. Those acts have separate scopes.</p><p>The governing claim is <code>muhurta.gruhapravesha</code>. Its bibliographic authority is B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, UBS Publishers&#39; Distributors, 1993. The cited Chapter XII passage, “House building,” section “Entering a new house,” was inspected in the distinct 2020 Chistabo derivative at internal printed pages 52–54 (physical PDF pages 56–58). Raman&#39;s work is a modern secondary authority rather than scripture.</p><h2 id="automated-crosswalk" tabindex="-1">Automated crosswalk <a class="header-anchor" href="#automated-crosswalk" aria-label="Permalink to &quot;Automated crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Criterion</th><th>Raman passage</th><th>Product treatment</th></tr></thead><tbody><tr><td>Tithi</td><td>Krishna Pratipat; Shukla Dwitiya, Tritiya, Panchami, Saptami, Dashami, Ekadashi and Trayodashi</td><td>Exact Paksha-qualified hard gate</td></tr><tr><td>Vara</td><td>Monday, Wednesday, Thursday and Friday</td><td>Exact sunrise-weekday hard gate</td></tr><tr><td>Nakshatra</td><td>Rohini, Mrigashira, Uttara Ashadha, Chitra and Uttara Bhadrapada best; Anuradha and Revati permissible</td><td>All seven admitted; no invented score difference</td></tr><tr><td>Solar state</td><td>Surya in Uttarayana</td><td>Makara through Mithuna hard gate, the traditional six-Rasi mapping</td></tr><tr><td>Lagna</td><td>Fixed preferred; dual ordinary; movable generally avoided except with Vrishabha Navamsa</td><td>Fixed and dual Rasis admitted, with a fixed-Rasi bonus; movable exception omitted because Navamsa is not computed across every surface</td></tr></tbody></table><p>Omitting the movable-Rasi exception is conservative: it can reject a source exception, but it cannot admit a time Raman rejects. The UI and MCP response state that boundary explicitly.</p><h2 id="browser-computed-and-manual-prerequisites" tabindex="-1">Browser-computed and manual prerequisites <a class="header-anchor" href="#browser-computed-and-manual-prerequisites" aria-label="Permalink to &quot;Browser-computed and manual prerequisites&quot;">​</a></h2><p>The Drik browser post-screen rejects an occupied 8th at any sampled state. Selecting a primary householder also turns a match to that person&#39;s Janma Rasi, Nakshatra or Lagna across every sampled state into one source preference without a raw-score bonus. Samples cover the window edges and both sides of every known interior Drik Lagna transition. A practitioner must still review Guru, Shukra and Chandra strength; malefics in Upachayas; benefics in Kendras; and preferably a Guru- or Shukra-owned rising Rasi. Worship and Bhootabali precede entry. Python/MCP retain the full list as manual checks because they do not call the chart service. See <a href="./54-muhurtam-election-chart-screening">Muhurtam election-chart screening</a>.</p><p>Raman advises against the entry after six months of the wife&#39;s pregnancy. Maternal comfort, clinician instructions and medical care always take precedence; the timing profile makes no health or pregnancy-outcome claim.</p><h2 id="published-practice-divergence" tabindex="-1">Published-practice divergence <a class="header-anchor" href="#published-practice-divergence" aria-label="Permalink to &quot;Published-practice divergence&quot;">​</a></h2><p>Drik Panchang&#39;s 2026 Griha Pravesh methodology and date table reject Sunday and Tuesday but admit qualifying Saturdays. Raman names Monday, Wednesday, Thursday and Friday, mentioning Saturday only as another-writers&#39; view with a theft caution. Drik Panchang also applies lunar-month and Adhika-month filters not imported into this Raman profile.</p><p>The disagreement is recorded as <code>muhurta.gruhapravesha.drkpanchang_divergence</code>. The application names and follows one lineage instead of silently blending both.</p>',13)])])}const m=e(n,[["render",s]]);export{p as __pageData,m as default};
